if (!function_exists('format_metric_number')) {
    function format_metric_number($num) {
        if ($num === null || $num === '') return '0';
        $n = (float)$num;
        if ($n >= 1000000) {
            return round($n / 1000000, 1) . 'M';
        } else if ($n >= 1000) {
            return round($n / 1000, 1) . 'K';
        }
        return number_format($n);
    }
}
if (!function_exists('format_currency_short')) {
    function format_currency_short($num) {
        if ($num === null || $num === '' || (float)$num <= 0) return '0';
        $n = (float)$num;
        if ($n >= 1000000) {
            $val = $n / 1000000;
            if ($val >= 1000) {
                return number_format($val, 0, ',', '.') . 'Jt';
            } else if ($val >= 100) {
                return round($val, 0) . 'Jt';
            } else {
                return round($val, 1) . 'Jt';
            }
        } else if ($n >= 1000) {
            return round($n / 1000, 1) . 'K';
        }
        return number_format($n, 0, ',', '.');
    }
}
