<!-- Page script -->
<script>
  $(document).ready(function(){
    $('[data-toggle="tooltip"]').tooltip();
   
    $(document).on('click', '.btn-approve-kol', function(e){
      e.preventDefault();
      var url = $(this).attr('data-href');
      var name = $(this).attr('data-name') || 'KOL ini';

      swal({
          title: "Terima Pendaftaran KOL?",
          text: "Apakah Anda yakin ingin menyetujui (accept) pendaftaran " + name + "? Akun login KOL akan diaktifkan.",
          type: "info",
          showCancelButton: true,
          confirmButtonColor: "#00a65a",
          confirmButtonText: "Ya, Terima!",
          cancelButtonText: "Batal",
          closeOnConfirm: true,
          closeOnCancel: true
        },
        function(isConfirm){
          if (isConfirm) {
            document.location.href = url;            
          }
        });

      return false;
    });

    $(document).on('click', '.btn-reject-kol', function(e){
      e.preventDefault();
      var url = $(this).attr('data-href');
      var name = $(this).attr('data-name') || 'KOL ini';

      swal({
          title: "Tolak Pendaftaran KOL?",
          text: "Apakah Anda yakin ingin menolak (reject) pendaftaran " + name + "? Data pendaftaran akan dihapus.",
          type: "warning",
          showCancelButton: true,
          confirmButtonColor: "#DD6B55",
          confirmButtonText: "Ya, Tolak!",
          cancelButtonText: "Batal",
          closeOnConfirm: true,
          closeOnCancel: true
        },
        function(isConfirm){
          if (isConfirm) {
            document.location.href = url;            
          }
        });

      return false;
    });

    $(document).on('click', '.remove-data', function(e){
      e.preventDefault();
      var url = $(this).attr('data-href');

      swal({
          title: "<?= cclang('are_you_sure'); ?>",
          text: "<?= cclang('data_to_be_deleted_can_not_be_restored'); ?>",
          type: "warning",
          showCancelButton: true,
          confirmButtonColor: "#DD6B55",
          confirmButtonText: "<?= cclang('yes_delete_it'); ?>",
          cancelButtonText: "<?= cclang('no_cancel_plx'); ?>",
          closeOnConfirm: true,
          closeOnCancel: true
        },
        function(isConfirm){
          if (isConfirm) {
            document.location.href = url;            
          }
        });

      return false;
    });

    // === SINGLE SCRAPE (per row) ===
    $(document).on('click', '.btn-scrape-single', function(e) {
        e.preventDefault();
        var el = $(this);
        var kolId = el.data('kol-id');
        var origHtml = el.html();

        el.html('<i class="fa fa-spinner fa-spin"></i>').css('pointer-events', 'none');
        toastr.info('Scraping KOL #' + kolId + '...');

        var postData = {};
        postData[csrf] = token;

        $.ajax({
            url: BASE_URL + 'administrator/scraping/scrape_single/' + kolId,
            type: 'POST',
            data: postData,
            dataType: 'json',
            timeout: 300000,
            success: function(res) {
                el.html(origHtml).css('pointer-events', '');
                if (res.success) {
                    toastr.success('KOL #' + kolId + ' scraped successfully');
                    setTimeout(function() {
                        location.reload();
                    }, 1500);
                } else {
                    toastr.warning(res.message || 'Some platforms failed');
                }
            },
            error: function() {
                el.html(origHtml).css('pointer-events', '');
                toastr.error('Network error scraping KOL #' + kolId);
            }
        });
    });

    // === Filter Toolbar Collapse Toggle Events ===
    $('#filterToolbarCollapse').on('show.bs.collapse', function () {
        $('#filterChevron').removeClass('fa-chevron-down').addClass('fa-chevron-up');
        $('#filterToggleText').text('Tutup Filter');
    });
    $('#filterToolbarCollapse').on('hide.bs.collapse', function () {
        $('#filterChevron').removeClass('fa-chevron-up').addClass('fa-chevron-down');
        $('#filterToggleText').text('Buka Filter');
    });

  }); /*end doc ready*/
</script>